using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RoomReservation.Infrastructure.Persistence;using RoomReservation.Domain.Entities;using RoomReservation.Domain.Enums;using System.Security.Claims;
namespace RoomReservation.Api.Controllers;
[ApiController,Microsoft.AspNetCore.Authorization.Authorize,Route("api/v1/bookings")]
public class BookingsController(AppDbContext db,RoomReservation.Api.Hubs.ReservationEvents events):ControllerBase{
 Guid Org=>Guid.Parse(User.FindFirstValue("organization_id")!);Guid UserId=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 IQueryable<Room> BookableRooms()=>db.Rooms.Where(r=>r.OrganizationId==Org||db.RoomAccesses.Any(a=>a.RoomId==r.Id&&a.OrganizationId==Org&&a.CanView&&a.CanBook));
 public record BookingInput(Guid RoomId,string Title,DateTime StartAtUtc,DateTime EndAtUtc,int? AttendeeCount=null,string? Notes=null);public record RecurringInput(Guid RoomId,string Title,DateTime StartAtUtc,DateTime EndAtUtc,int Weeks);
 [HttpGet]public async Task<IEnumerable<Booking>>List(Guid? room_id=null,DateTime? date=null,bool includeHistory=false){var q=db.Bookings.Where(x=>x.OrganizationId==Org);if(!includeHistory)q=q.Where(x=>x.Status!=BookingStatus.Cancelled&&x.Status!=BookingStatus.NoShow);if(room_id.HasValue)q=q.Where(x=>x.RoomId==room_id);if(date.HasValue){var d=DateTime.SpecifyKind(date.Value.Date,DateTimeKind.Utc);q=q.Where(x=>x.StartAtUtc<d.AddDays(1)&&x.EndAtUtc>d);}return await q.OrderBy(x=>x.StartAtUtc).ToListAsync();}
 [HttpGet("page")]public async Task<IActionResult>Page(int page=1,int pageSize=20,bool includeHistory=false,string? scope=null,string? search=null,Guid? room_id=null,string? building=null,string? floor=null,int? status=null,DateTime? date=null){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=from b in db.Bookings join r in db.Rooms on b.RoomId equals r.Id where b.OrganizationId==Org select new{b,r};if(!includeHistory)q=q.Where(x=>x.b.Status!=BookingStatus.Cancelled&&x.b.Status!=BookingStatus.NoShow);if(scope=="upcoming")q=q.Where(x=>x.b.EndAtUtc>=DateTime.UtcNow&&(x.b.Status==BookingStatus.Pending||x.b.Status==BookingStatus.Confirmed||x.b.Status==BookingStatus.CheckedIn));if(scope=="past")q=q.Where(x=>x.b.EndAtUtc<DateTime.UtcNow);if(room_id.HasValue)q=q.Where(x=>x.b.RoomId==room_id);if(status.HasValue)q=q.Where(x=>(int)x.b.Status==status);if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.b.Title.Contains(term)||x.r.Name.Contains(term));}if(!string.IsNullOrWhiteSpace(building))q=q.Where(x=>x.r.Building==building);if(!string.IsNullOrWhiteSpace(floor))q=q.Where(x=>x.r.Floor==floor);if(date.HasValue){var d=DateTime.SpecifyKind(date.Value.Date,DateTimeKind.Utc);q=q.Where(x=>x.b.StartAtUtc<d.AddDays(1)&&x.b.EndAtUtc>d);}var total=await q.CountAsync();var items=await q.OrderByDescending(x=>x.b.StartAtUtc).Skip((page-1)*pageSize).Take(pageSize).Select(x=>x.b).ToListAsync();return Ok(new{items,total,page,pageSize,totalPages=(int)Math.Ceiling(total/(double)pageSize)});}
 [HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id){var b=await db.Bookings.FirstOrDefaultAsync(x=>x.Id==id&&x.OrganizationId==Org);if(b is null)return NotFound();var room=await db.Rooms.FirstOrDefaultAsync(x=>x.Id==b.RoomId);var user=await db.Users.FirstOrDefaultAsync(x=>x.Id==b.UserId);var org=await db.Organizations.FirstOrDefaultAsync(x=>x.Id==b.OrganizationId);var checkIn=await db.CheckInEvents.FirstOrDefaultAsync(x=>x.BookingId==b.Id);return Ok(new{b.Id,b.OrganizationId,b.RoomId,b.UserId,b.RecurringSeriesId,b.Title,b.AttendeeCount,b.Notes,b.StartAtUtc,b.EndAtUtc,b.Status,b.CreatedAt,b.UpdatedAt,room=new{name=room?.Name,building=room?.Building,floor=room?.Floor,capacity=room?.Capacity,equipmentTags=room?.EquipmentTags,photoUrls=room?.PhotoUrls},organizer=new{displayName=user?.DisplayName,email=user?.Email},organization=org?.Name,checkIn});}
 [HttpPost]public async Task<IActionResult>Create(BookingInput i){var room=await BookableRooms().FirstOrDefaultAsync(r=>r.Id==i.RoomId);if(room is null)return Forbid();var access=room.OrganizationId==Org?null:await db.RoomAccesses.AsNoTracking().FirstOrDefaultAsync(a=>a.RoomId==room.Id&&a.OrganizationId==Org&&a.CanBook);if(room.OrganizationId!=Org&&access is null)return Forbid();var attendeeCount=i.AttendeeCount??1;if(!Valid(i.StartAtUtc,i.EndAtUtc)||attendeeCount<1||string.IsNullOrWhiteSpace(i.Title))return BadRequest();if(await Collision(i.RoomId,i.StartAtUtc,i.EndAtUtc))return Conflict("Room is already booked");var b=new Booking{OrganizationId=Org,UserId=UserId,RoomId=i.RoomId,BookingSource=room.OrganizationId==Org?"Internal":"Shared",Title=i.Title.Trim(),AttendeeCount=attendeeCount,Notes=string.IsNullOrWhiteSpace(i.Notes)?null:i.Notes.Trim(),Status=room.RequiresApproval||access?.RequiresApproval==true?BookingStatus.Pending:BookingStatus.Confirmed,StartAtUtc=Utc(i.StartAtUtc),EndAtUtc=Utc(i.EndAtUtc)};db.Bookings.Add(b);await db.SaveChangesAsync();await events.Created(b);return CreatedAtAction(nameof(Get),new{id=b.Id},b);}
 [HttpPatch("{id:guid}")]public async Task<IActionResult>Update(Guid id,BookingInput i){var canManage=User.IsInRole("OrgAdmin")||User.IsInRole("Admin")||User.IsInRole("SuperAdmin");var b=await db.Bookings.FirstOrDefaultAsync(x=>x.Id==id&&x.OrganizationId==Org&&(x.UserId==UserId||canManage));if(b is null)return NotFound();if(b.Status==BookingStatus.CheckedIn||b.StartAtUtc<=DateTime.UtcNow)return BadRequest("Booking cannot be edited");if(!await BookableRooms().AnyAsync(r=>r.Id==i.RoomId)||!Valid(i.StartAtUtc,i.EndAtUtc)||(i.AttendeeCount.HasValue&&i.AttendeeCount<1)||string.IsNullOrWhiteSpace(i.Title))return BadRequest();if(await Collision(i.RoomId,i.StartAtUtc,i.EndAtUtc,id))return Conflict("Room is already booked");b.RoomId=i.RoomId;b.Title=i.Title.Trim();if(i.AttendeeCount.HasValue)b.AttendeeCount=i.AttendeeCount.Value;if(i.Notes is not null)b.Notes=string.IsNullOrWhiteSpace(i.Notes)?null:i.Notes.Trim();b.StartAtUtc=Utc(i.StartAtUtc);b.EndAtUtc=Utc(i.EndAtUtc);b.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await events.Updated(b);return Ok(b);}
 [HttpPost("{id:guid}/cancel")]public async Task<IActionResult>Cancel(Guid id){var b=await db.Bookings.FirstOrDefaultAsync(x=>x.Id==id&&x.OrganizationId==Org&&x.UserId==UserId);if(b is null)return NotFound();if(b.StartAtUtc<=DateTime.UtcNow)return BadRequest("Booking has started");b.Status=BookingStatus.Cancelled;b.UpdatedAt=DateTime.UtcNow;db.AuditLogs.Add(new Domain.Entities.AuditLog{OrganizationId=Org,ActorUserId=UserId,Action="booking.cancelled",TargetType="Booking",TargetId=b.Id,Metadata=System.Text.Json.JsonSerializer.Serialize(new{status=b.Status.ToString()})});await db.SaveChangesAsync();await events.Cancelled(b);return Ok(b);}
 [HttpPost("{id:guid}/extend")]public async Task<IActionResult>Extend(Guid id,int minutes=15){var b=await db.Bookings.FirstOrDefaultAsync(x=>x.Id==id&&x.OrganizationId==Org);if(b is null)return NotFound();if(b.Status!=BookingStatus.CheckedIn)return BadRequest("Booking is not checked in");var end=b.EndAtUtc.AddMinutes(minutes);if(await Collision(b.RoomId,b.EndAtUtc,end,id))return Conflict("Next slot is occupied");b.EndAtUtc=end;b.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await events.Updated(b);return Ok(b);}
 [HttpPost("recurring")]public async Task<IActionResult>Recurring(RecurringInput i){var room=await BookableRooms().FirstOrDefaultAsync(r=>r.Id==i.RoomId);if(room is null||i.Weeks<1||i.Weeks>52||!Valid(i.StartAtUtc,i.EndAtUtc)||string.IsNullOrWhiteSpace(i.Title))return BadRequest();var access=room.OrganizationId==Org?null:await db.RoomAccesses.AsNoTracking().FirstOrDefaultAsync(a=>a.RoomId==room.Id&&a.OrganizationId==Org&&a.CanBook);if(room.OrganizationId!=Org&&access is null)return Forbid();var series=new RecurringSeries{OrganizationId=Org,UserId=UserId,RoomId=i.RoomId,Title=i.Title.Trim(),SeriesStartDate=i.StartAtUtc.Date,SeriesEndDate=i.StartAtUtc.Date.AddDays(i.Weeks*7)};db.Add(series);for(var n=0;n<i.Weeks;n++){var b=new Booking{OrganizationId=Org,UserId=UserId,RoomId=i.RoomId,BookingSource=room.OrganizationId==Org?"Internal":"Shared",Title=i.Title.Trim(),RecurringSeriesId=series.Id,Status=room.RequiresApproval||access?.RequiresApproval==true?BookingStatus.Pending:BookingStatus.Confirmed,StartAtUtc=Utc(i.StartAtUtc.AddDays(n*7)),EndAtUtc=Utc(i.EndAtUtc.AddDays(n*7))};if(await Collision(b.RoomId,b.StartAtUtc,b.EndAtUtc))return Conflict("Recurring occurrence collides");db.Add(b);}await db.SaveChangesAsync();return Ok(series);}
 static bool Valid(DateTime s,DateTime e)=>Utc(s)>DateTime.UtcNow&&e>s&&e-s>=TimeSpan.FromMinutes(15);static DateTime Utc(DateTime x)=>x.Kind==DateTimeKind.Utc?x:x.ToUniversalTime();async Task<bool>Collision(Guid room,DateTime s,DateTime e,Guid? except=null)=>await db.Bookings.AnyAsync(x=>x.RoomId==room&&x.Id!=except&&x.Status!=BookingStatus.Cancelled&&x.Status!=BookingStatus.NoShow&&x.StartAtUtc<e&&s<x.EndAtUtc);
}
